class CosmosQuery
{
    async Task FindProducts(ProductContext ctx)
    {
        // Direct Cosmos SQL — still works because we explicitly kept "Discriminator" property name.
        // If we had NOT configured HasDiscriminator("Discriminator"), EF9 would write "$type" instead
        // and this query would return zero results against existing docs.
        var sql = "SELECT * FROM c WHERE c.Discriminator = 'Product' AND c.Sku = @sku";

        // EF Core 9 breaking change: synchronous I/O is no longer supported.
        // .ToList() throws — use async alternatives.
        var products = await ctx.Products
            .Where(p => p.Sku == "ABC")
            .ToListAsync();
    }
}

